:root { --bg:#f5f6f8; --card:#fff; --line:#e4e6eb; --ink:#1c1e21; --sub:#65676b; --accent:#2f6fed; }
* { box-sizing:border-box; }
body { margin:0; font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
       background:var(--bg); color:var(--ink); }
header { background:var(--card); border-bottom:1px solid var(--line); padding:14px 20px; }
header h1 { margin:0; font-size:17px; }
header .tag { font-size:12px; color:var(--sub); }
.wrap { max-width:900px; margin:0 auto; padding:18px 16px 60px; display:flex; gap:20px; }
.side { flex:0 0 190px; }
.side h2 { font-size:12px; text-transform:uppercase; letter-spacing:.04em; color:var(--sub); margin:0 0 8px; }
.side button { display:block; width:100%; text-align:left; background:transparent; border:0;
  padding:9px 11px; border-radius:8px; font-size:14px; cursor:pointer; color:var(--ink); }
.side button:hover { background:#eef1f6; }
.side button.active { background:var(--accent); color:#fff; }
.side .count { float:right; opacity:.7; font-size:12px; }
.main { flex:1; min-width:0; }
.topbar { display:flex; flex-wrap:wrap; gap:8px; margin-bottom:14px; }
.pill { background:#eef1f6; border:0; border-radius:20px; padding:6px 13px; font-size:13px;
  cursor:pointer; color:var(--ink); }
.pill.active { background:var(--accent); color:#fff; }
.card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:13px 15px;
  margin-bottom:11px; display:flex; gap:12px; align-items:flex-start; }
.fav { width:26px; height:26px; border-radius:6px; background:#eef1f6; flex:0 0 auto; overflow:hidden;
  display:flex; align-items:center; justify-content:center; font-size:14px; }
.fav img { width:100%; height:100%; object-fit:cover; }
.body { min-width:0; flex:1; }
.title { font-size:15px; font-weight:600; margin:0 0 2px; word-break:break-word; }
.desc { font-size:13px; color:#3a3c40; margin:0 0 5px; }
.url { font-size:12px; color:var(--sub); margin:0; }
.chips { margin-top:8px; }
.chip { display:inline-block; background:#eef1f6; border-radius:16px; padding:3px 9px; font-size:12px;
  margin:3px 5px 0 0; color:#333; }
.chip .x { cursor:pointer; margin-left:5px; color:var(--sub); }
.chip.add { background:transparent; border:1px dashed var(--line); cursor:pointer; color:var(--sub); }
.move { margin-top:8px; font-size:13px; }
.move select { padding:5px 8px; border:1px solid var(--line); border-radius:7px; font-size:13px; }
.grouphead { font-size:13px; font-weight:600; color:var(--sub); margin:16px 0 8px; display:flex;
  align-items:center; gap:8px; }
.grouphead img { width:18px; height:18px; border-radius:4px; }
.note { background:#fff8e1; border:1px solid #f2e2a8; border-radius:10px; padding:11px 14px;
  font-size:13px; color:#5a4b16; margin-bottom:16px; }
@media (max-width:640px){ .wrap{flex-direction:column;} .side{flex:auto;}
  .side button{display:inline-block;width:auto;} }

