function allTags(){ var s={}; items.forEach(function(it){ (it.tags||[]).forEach(function(t){s[t]=1;}); });
  return Object.keys(s).sort(); }
function matchesQuery(it, q){
  if(!q) return true;
  var hay = (it.title+' '+it.desc+' '+it.url+' '+(it.tags||[]).join(' ')).toLowerCase();
  return q.toLowerCase().split(/\s+/).every(function(w){ return !w || hay.indexOf(w)>=0; });
}
function highlight(text, q){
  var out = escapeHtml(text);
  if(!q) return out;
  q.toLowerCase().split(/\s+/).filter(Boolean).forEach(function(w){
    var re = new RegExp('('+w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','ig');
    out = out.replace(re,'<mark>$1</mark>');
  });
  return out;
}

