input.new_string:
function render(){
  renderTagbar();
  searchbarEl.style.display = items.length ? 'block' : 'none';
  var shown = items.filter(function(it){
    return activeTags.every(function(t){ return (it.tags||[]).indexOf(t)>=0; })
           && matchesQuery(it, query);
  });
  var filtering = activeTags.length || query;
  listheadEl.textContent = filtering
    ? shown.length+' of '+items.length+' bookmarks'
    : 'Saved links';
  if(items.length===0){
    listEl.innerHTML = '<div class="empty">No links saved yet. Paste one above to get started.</div>';
    return;
  }
  if(shown.length===0){
    var msg = query
      ? 'No bookmarks match “'+escapeHtml(query)+'”'+(activeTags.length?' with the selected tags.':'.')
      : 'No bookmarks have all the selected tags.';
    listEl.innerHTML = '<div class="empty">'+msg+'</div>';
    return;
  }

