// ---- Search query language ------------------------------------------------
// Supports: bare words (substring), "quoted phrases", #tag, AND/OR/NOT and
// parentheses. Implicit AND between adjacent terms. NOT > AND > OR. A quoted
// token is always a literal, even if it spells an operator.
function tokenize(q){
  var toks=[], i=0, n=q.length;
  while(i<n){
    var c=q[i];
    if(c===' '||c==='\t'){ i++; continue; }
    if(c==='('){ toks.push({t:'('}); i++; continue; }
    if(c===')'){ toks.push({t:')'}); i++; continue; }
    if(c==='"'){ var j=i+1,s=''; while(j<n&&q[j]!=='"'){ s+=q[j++]; } i=(j<n)?j+1:j;
      toks.push({t:'term',kind:'phrase',val:s.toLowerCase()}); continue; }
    if(c==='#'){ var k=i+1,tg=''; while(k<n&&/[^\s()"]/.test(q[k])){ tg+=q[k++]; } i=k;
