    // fenced code block
    if(/^```/.test(ln)){
      var buf=[]; i++;
      while(i<lines.length && !/^```/.test(lines[i])){ buf.push(lines[i]); i++; }
      i++; out.push('<pre><code>'+buf.join('\n')+'</code></pre>'); continue;
    }
    var h=ln.match(/^(#{1,6})\s+(.*)$/);
    if(h){ var lvl=Math.min(h[1].length,4); out.push('<h'+lvl+'>'+mdInline(h[2])+'</h'+lvl+'>'); i++; continue; }
    if(/^\s*[-*]\s+/.test(ln)){
      out.push('<ul>');
      while(i<lines.length && /^\s*[-*]\s+/.test(lines[i])){
        out.push('<li>'+mdInline(lines[i].replace(/^\s*[-*]\s+/,''))+'</li>'); i++; }
      out.push('</ul>'); continue;
    }
    if(/^\s*\d+\.\s+/.test(ln)){
      out.push('<ol>');
      while(i<lines.length && /^\s*\d+\.\s+/.test(lines[i])){
        out.push('<li>'+mdInline(lines[i].replace(/^\s*\d+\.\s+/,''))+'</li>'); i++; }
      out.push('</ol>'); continue;
    }
    if(/^\s*$/.test(ln)){ i++; continue; }
    // paragraph: gather consecutive non-blank, non-special lines
    var para=[];
