// ---- bulk selection & actions -------------------------------------------
var bulkbarEl=document.getElementById('bulkbar');
var inArchiveView=function(){ return statusView==='archived'; };
function selectedItems(){ var a=[]; selected.forEach(function(id){ var it=byId(id); if(it) a.push(it); }); return a; }
function updateBulkbar(){
  var n=selected.size;
  bulkbarEl.style.display = n>0 ? 'block' : 'none';
  if(n===0) return;
  document.getElementById('bulkcount').textContent = n+' selected';
  // select-all-matching label
  var matchN=lastShownIds.length;
  var allSelected = matchN>0 && lastShownIds.every(function(id){ return selected.has(id); });
  document.getElementById('selectall').textContent =
    allSelected ? 'Clear all '+matchN+' matching' : 'Select all '+matchN+' matching';
  // archive vs restore label depends on view
  document.getElementById('bulk-arch').textContent = inArchiveView() ? 'Restore' : 'Archive';
  // hide read/unread + archive-as-archive appropriately in archive view
  document.getElementById('bulk-read').style.display = inArchiveView() ? 'none':'';
  document.getElementById('bulk-unread').style.display = inArchiveView() ? 'none':'';
}
function bumpUpdated(it){ it.updated=new Date(); }
function refreshTaglist(){
  document.getElementById('bulk-taglist').innerHTML =
    allTags().map(function(t){ return '<option value="'+escapeHtml(t)+'">'; }).join('');
}
var bulkTagMode=null; // 'add' | 'remove'
function openBulkTag(mode){
  bulkTagMode=mode; refreshTaglist();
  document.getElementById('bulk-taginput').style.display='flex';
  document.getElementById('bulk-tag-mode').textContent =
    mode==='add' ? 'Add this tag to '+selected.size+' bookmarks' : 'Remove this tag from '+selected.size+' bookmarks';
  var f=document.getElementById('bulk-tagfield'); f.value=''; f.focus();
}
function closeBulkTag(){ document.getElementById('bulk-taginput').style.display='none'; bulkTagMode=null; }
function applyBulkTag(){
  var t=document.getElementById('bulk-tagfield').value.trim().toLowerCase().replace(/^#/,'');
  if(!t) return;
