function snapUrl(it){
  return 'snapshot.html?title='+encodeURIComponent(it.title)+'&url='+encodeURIComponent(it.url)+
         '&date='+encodeURIComponent(it.snapshot?fmtDate(it.snapshot.date):'')+
         (it.isPdf?'&kind=pdf':'');
}
function offlineHtml(it){
  var label = it.isPdf ? 'Saved PDF' : 'Saved copy';
  var kindWord = it.isPdf ? 'the PDF file' : 'a copy of this page';
  var h = '<div class="offline-title">Offline copy</div>';
  if(it.snapshot){
    h += '<p class="offline-line">✅ '+label+' from '+fmtDate(it.snapshot.date)+' — '+
         '<a href="'+snapUrl(it)+'" target="_blank" rel="noopener">View saved copy</a> '+
         '<button class="ctl-link" data-snap-refresh="'+it.id+'">Update copy</button> '+
         '<button class="ctl-link danger-link" data-snap-remove="'+it.id+'">Remove copy</button></p>';
  } else {
    h += '<p class="offline-line"><button class="ghost" data-snap="'+it.id+'">Save '+kindWord+'</button> '+
         '<span class="hint">keeps it readable if the original changes or disappears</span></p>';
  }
  if(it.wayback){
    h += '<p class="offline-line">🌐 Preserved on the Internet Archive ('+fmtDate(it.wayback.date)+') — '+
         '<a href="'+it.wayback.url+'" target="_blank" rel="noopener">View on web.archive.org</a></p>';
  } else {
    h += '<p class="offline-line"><button class="ghost" data-wayback="'+it.id+'">Also preserve via Internet Archive</button></p>';
  }
  return h;
}
