// ---- import / export (Netscape bookmark file) ----------------------------
function exportBookmarks(){
  var lines = ['<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>','<H1>Bookmarks</H1>','<DL><p>'];
  items.forEach(function(it){
    var add=Math.floor(it.saved.getTime()/1000), mod=Math.floor((it.updated||it.saved).getTime()/1000);
    var attrs='HREF="'+escapeHtml(it.url)+'" ADD_DATE="'+add+'" LAST_MODIFIED="'+mod+'"';
    if(it.tags&&it.tags.length) attrs+=' TAGS="'+escapeHtml(it.tags.join(','))+'"';
    lines.push('    <DT><A '+attrs+'>'+escapeHtml(it.title)+'</A>');
    if(it.note) lines.push('    <DD>'+escapeHtml(it.note));
  });
  lines.push('</DL><p>');
  var blob=new Blob([lines.join('\n')],{type:'text/html'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download='bookmarks-'+new Date().toISOString().slice(0,10)+'.html';
  document.body.appendChild(a); a.click(); a.remove();
  toast('Exported '+items.length+' bookmark'+(items.length===1?'':'s')+'.');
}
function importBookmarks(text){
  var doc=new DOMParser().parseFromString(text,'text/html');
  var anchors=doc.querySelectorAll('a[href]');
  var added=0, skipped=0;
  anchors.forEach(function(a){
    var url=normalize(a.getAttribute('href')||'');
    if(!validUrl(url)){ skipped++; return; }
    if(findByUrl(url)){ skipped++; return; }
    var addDate=a.getAttribute('add_date');
    var saved=addDate? new Date(parseInt(addDate,10)*1000) : new Date();
    if(isNaN(saved.getTime())) saved=new Date();
    var tagsAttr=a.getAttribute('tags')||'';
    var tags=tagsAttr.split(',').map(function(t){return t.trim().toLowerCase();}).filter(Boolean);
    var dd=a.parentNode && a.parentNode.nextElementSibling;
    var note=(dd && dd.tagName==='DD')? dd.textContent.trim() : '';
    var m=fetchMeta(url);
    items.push({ id:++seq, url:url, title:(a.textContent||'').trim()||m.title, desc:m.desc,
      icon:m.icon, image:m.image, saved:saved, updated:saved, editing:false,
      tags:tags, read:false, note:note, archived:false,
      isPdf:/\.pdf(\?|$)/i.test(url), snapshot:null, wayback:null });
    added++;
  });
  render();
  toast('Imported '+added+' bookmark'+(added===1?'':'s')+
        (skipped?(', skipped '+skipped+' already saved or invalid'):'')+'.');
}
document.getElementById('exportbtn').addEventListener('click', exportBookmarks);
document.getElementById('importbtn').addEventListener('click', function(){ document.getElementById('importfile').click(); });
document.getElementById('importfile').addEventListener('change', function(e){
  var f=e.target.files[0]; if(!f) return;
  var r=new FileReader();
  r.onload=function(){ importBookmarks(String(r.result)); };
  r.readAsText(f); e.target.value='';
});

render(); refreshButton();
document.body.setAttribute('data-harness-ready','true');

