      try {
        var w = await wayback.preserve(b.url);
        b.wayback = w; store.save();
        return sendJson(res, 200, { wayback: w });
      } catch (e) {
        return sendJson(res, 502, { error: 'Internet Archive preservation failed: ' + e.message + ' You can retry.' });
      }
    }
  }

