    var html = matches.map(function (t) { return '<div data-pick="' + esc(t) + '">#' + esc(t) + '</div>'; }).join('');
    if (q && allTags().indexOf(q) < 0 && have.indexOf(q) < 0) html += '<div class="new" data-pick="' + esc(q) + '">+ create “' + esc(q) + '”</div>';
